def count_vowels(text):
    count = 0
    for character in text:
        if character.lower() in 'aeiou':
            count += 1
    return count

def average(numbers):
    if not numbers:
        return None
    return sum(numbers) / len(numbers)

def count_words(words):
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return counts

class Counter:
    def __init__(self):
        self.value = 0

    def increment(self):
        self.value += 1
        return self.value

def is_balanced(text):
    stack = []
    for character in text:
        if character == '(':
            stack.append(character)
        elif character == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

def is_palindrome(text):
    left = 0
    right = len(text) - 1
    while left < right:
        if text[left] != text[right]:
            return False
        left += 1
        right -= 1
    return True

def find_maximum(numbers):
    if not numbers:
        return None
    best = numbers[0]
    for number in numbers:
        if number > best:
            best = number
    return best

def two_sum(numbers, target):
    seen = {}
    for index, number in enumerate(numbers):
        complement = target - number
        if complement in seen:
            return (seen[complement], index)
        if number not in seen:
            seen[number] = index
    return None
